    bullseye: await iconToBase64Png(FaBullseye, "#" + C.accent, 256),
  };

  // ════════════════════════════════════════════════
  // SLIDE 1: Title
  // ════════════════════════════════════════════════
  {
    const slide = pres.addSlide();
    slide.background = { color: C.navy };

    // Decorative top-left shape
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 0.12, h: 5.625, fill: { color: C.accent }
    });

    // Icon top area
    slide.addImage({ data: icons.chart, x: 0.7, y: 0.6, w: 0.7, h: 0.7 });

    slide.addText("State of the Web\n2020–2025", {
      x: 0.7, y: 1.5, w: 8.5, h: 1.8,
      fontFace: FONT_HEAD, fontSize: 42, color: C.white, bold: true,
