      x: 0.7, y: 1.6, w: 3.8, h: 2.8, fill: { color: C.midnight },
      shadow: mkShadow()
    });
    slide.addText("99%+", {
      x: 0.7, y: 1.7, w: 3.8, h: 1.5,
      fontFace: FONT_HEAD, fontSize: 72, bold: true, color: C.accent, align: "center", margin: 0
    });
    slide.addText([
      { text: "Desktop: 99.2%", options: { breakLine: true, fontSize: 16, color: C.white, fontFace: FONT_BODY } },
      { text: "Mobile: 99.1%", options: { fontSize: 16, color: C.white, fontFace: FONT_BODY } }
    ], { x: 0.7, y: 3.2, w: 3.8, h: 0.9, align: "center", margin: 0 });

    slide.addText("▲ ~19–20 pp since 2020 (~80%)", {
      x: 0.7, y: 4.1, w: 3.8, h: 0.35,
