10,\n      legendColor: C.bodyText,\n    });\n\n    // Right-side stat cards\n    const cardX = 7.0, cardW = 2.6;\n    // Card: Desktop\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: cardX, y: 1.8, w: cardW, h: 1.3, fill: { color: C.white },\n      shadow: mkShadow()\n    });\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: cardX, y: 1.8, w: 0.08, h: 1.3, fill: { color: C.deepBlue }\n    });\n    slide.addText(\"~2,000 KB\", {\n      x: cardX + 0.25, y: 1.85, w: cardW - 0.3, h: 0.7,\n      fontFace: FONT_HEAD, fontSize: 28, bold: true, color: C.deepBlue, margin: 0\n    });\n    slide.addText(\"Desktop median (▲ 25%)\", {\n      x: cardX + 0.25, y: 2.55, w: cardW - 0.3, h: 0.4,\n      fontFace: FONT_BODY, fontSize: 11, color: C.midGray, margin: 0\n    });\n\n    // Card: Mobile\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: cardX, y: 3.35, w: cardW, h: 1.3, fill: { color: C.white },\n      shadow: mkShadow()\n    });\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: cardX, y: 3.35, w: 0.08, h: 1.3, fill: { color: C.accent }\n    });\n    slide.addText(\"~1,900 KB\", {\n      x: cardX + 0.25, y: 3.4, w: cardW - 0.3, h: 0.7,\n      fontFace: FONT_HEAD, fontSize: 28, bold: true, color: C.teal, margin: 0\n    });\n    slide.addText(\"Mobile median (▲ 25%)\", {\n      x: cardX + 0.25, y: 4.1, w: cardW - 0.3, h: 0.4,\n      fontFace: FONT_BODY, fontSize: 11, color: C.midGray, margin: 0\n    });\n\n    slide.addText(\"Source: HTTP Archive State of the Web\", {\n      x: 0.5, y: 5.2, w: 5, h: 0.35,\n      fontFace: FONT_BODY, fontSize: 9, color: C.midGray, margin: 0\n    });\n  }\n\n  // ════════════════════════════════════════════════\n  // SLIDE 4: Requests and Connections\n  // ════════════════════════════════════════════════\n  {\n    const slide = pres.addSlide();\n    slide.background = { color: C.offWhite };\n\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 0, y: 0, w: 10, h: 0.9, fill: { color: C.navy }\n    });\n    slide.addImage({ data: icons.exchange, x: 0.5, y: 0.18, w: 0.45, h: 0.45 });\n    slide.addText(\"76 Requests per Page, TCP Connections Drop to 12\", {\n      x: 1.1, y: 0.05, w: 8.5, h: 0.8,\n      fontFace: FONT_HEAD, fontSize: 24, color: C.white, bold: true, margin: 0\n    });\n\n    // LEFT SIDE: Stat cards for requests\n    const lx = 0.5;\n    // Desktop requests card\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: lx, y: 1.2, w: 4.2, h: 1.6, fill: { color: C.white },\n      shadow: mkShadow()\n    });\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: lx, y: 1.2, w: 0.08, h: 1.6, fill: { color: C.deepBlue }\n    });\n    slide.addText([\n      { text: \"76\", options: { fontSize: 48, bold: true, color: C.deepBlue, fontFace: FONT_HEAD, breakLine: true } },\n      { text: \"Desktop Requests / Page  (▲ 2.7%)\", options: { fontSize: 12, color: C.midGray, fontFace: FONT_BODY } }\n    ], { x: lx + 0.3, y: 1.3, w: 3.5, h: 1.4, margin: 0 });\n\n    // Mobile requests card\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: lx, y: 3.05, w: 4.2, h: 1.6, fill: { color: C.white },\n      shadow: mkShadow()\n    });\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: lx, y: 3.05, w: 0.08, h: 1.6, fill: { color: C.accent }\n    });\n    slide.addText([\n      { text: \"71\", options: { fontSize: 48, bold: true, color: C.teal, fontFace: FONT_HEAD, breakLine: true } },\n      { text: \"Mobile Requests / Page  (▲ 2.9%)\", options: { fontSize: 12, color: C.midGray, fontFace: FONT_BODY } }\n    ], { x: lx + 0.3, y: 3.15, w: 3.5, h: 1.4, margin: 0 });\n\n    // RIGHT SIDE: TCP connections declining chart\n    const labels = [\"Jan 2020\", \"Jul 2020\", \"Jan 2021\", \"Jul 2021\", \"Jan 2022\", \"Jul 2022\", \"Jan 2023\", \"Jul 2023\", \"Jan 2024\", \"Jul 2024\", \"Jan 2025\"];\n    const desktopTCP = [15, 14.8, 14.5, 14.2, 13.8, 13.5, 13, 12.7, 12.4, 12.2, 12];\n    const mobileTCP  = [15, 14.5, 14, 13.5, 13, 12.5, 12, 11.8, 11.5, 11.2, 11];\n\n    slide.addChart(pres.charts.LINE, [\n      { name: \"Desktop TCP Conn\", labels: labels, values: desktopTCP },\n      { name: \"Mobile TCP Conn\",  labels: labels, values: mobileTCP }\n    ], {\n      x: 5.1, y: 1.2, w: 4.5, h: 3.0,\n      showTitle: true,\n      title: \"TCP Connections / Page (median)\",\n      titleColor: C.bodyText,\n      titleFontSize: 11,\n      chartColors: [C.deepBlue, C.accent],\n      lineSize: 2.5,\n      lineSmooth: true,\n      showMarker: true,\n      markerSize: 4,\n      chartArea: { fill: { color: C.white }, roundedCorners: true },\n      catAxisLabelColor: C.midGray,\n      valAxisLabelColor: C.midGray,\n      catAxisLabelFontSize: 7,\n      valAxisLabelFontSize: 9,\n      valGridLine: { color: C.lightGray, size: 0.5 },\n      catGridLine: { style: \"none\" },\n      showLegend: true,\n      legendPos: \"b\",\n      legendFontSize: 9,\n      legendColor: C.bodyText,\n    });\n\n    slide.addText(\"▼ 14.3% desktop · ▼ 26.7% mobile — HTTP/2 & HTTP/3 multiplexing\", {\n      x: 5.1, y: 4.35, w: 4.5, h: 0.4,\n      fontFace: FONT_BODY, fontSize: 10, italic: true, color: C.teal, margin: 0\n    });\n\n    slide.addText(\"Source: HTTP Archive State of the Web\", {\n      x: 0.5, y: 5.2, w: 5, h: 0.35,\n      fontFace: FONT_BODY, fontSize: 9, color: C.midGray, margin: 0\n    });\n  }\n\n  // ════════════════════════════════════════════════\n  // SLIDE 5: HTTPS Near Universal\n  // ════════════════════════════════════════════════\n  {\n    const slide = pres.addSlide();\n    slide.background = { color: C.navy };\n\n    // Green left accent\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 0, y: 0, w: 0.12, h: 5.625, fill: { color: C.accent }\n    });\n\n    // Title\n    slide.addImage({ data: icons.lock, x: 0.7, y: 0.4, w: 0.45, h: 0.45 });\n    slide.addText(\"HTTPS Requests Reach 99%\", {\n      x: 1.3, y: 0.35, w: 8, h: 0.6,\n      fontFace: FONT_HEAD, fontSize: 28, color: C.white, bold: true, margin: 0\n    });\n    slide.addText(\"Encryption Is Now the Default\", {\n      x: 0.7, y: 0.95, w: 8, h: 0.4,\n      fontFace: FONT_BODY, fontSize: 16, color: C.midGray, margin: 0\n    });\n\n    // Large stat callout card\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 0.7, y: 1.6, w: 3.8, h: 2.8, fill: { color: C.midnight },\n      shadow: mkShadow()\n    });\n    slide.addText(\"99%+\", {\n      x: 0.7, y: 1.7, w: 3.8, h: 1.5,\n      fontFace: FONT_HEAD, fontSize: 72, bold: true, color: C.accent, align: \"center\", margin: 0\n    });\n    slide.addText([\n      { text: \"Desktop: 99.2%\", options: { breakLine: true, fontSize: 16, color: C.white, fontFace: FONT_BODY } },\n      { text: \"Mobile: 99.1%\", options: { fontSize: 16, color: C.white, fontFace: FONT_BODY } }\n    ], { x: 0.7, y: 3.2, w: 3.8, h: 0.9, align: \"center\", margin: 0 });\n\n    slide.addText(\"▲ ~19–20 pp since 2020 (~80%)\", {\n      x: 0.7, y: 4.1, w: 3.8, h: 0.35,\n      fontFace: FONT_BODY, fontSize: 11, italic: true, color: C.midGray, align: \"center\", margin: 0\n    });\n\n    // Small time-series line chart (right side)\n    const labels = [\"2020\", \"2021\", \"2022\", \"2023\", \"2024\", \"2025\"];\n    const httpsDesktop = [80, 85, 90, 95, 98, 99.2];\n    const httpsMobile  = [80, 84, 89, 94, 97.5, 99.1];\n\n    slide.addChart(pres.charts.LINE, [\n      { name: \"Desktop\", labels: labels, values: httpsDesktop },\n      { name: \"Mobile\",  labels: labels, values: httpsMobile }\n    ], {\n      x: 5.0, y: 1.6, w: 4.5, h: 2.8,\n      showTitle: true,\n      title: \"HTTPS Adoption Over Time (%)\",\n      titleColor: C.midGray,\n      titleFontSize: 10,\n      chartColors: [C.accent, \"FFCC44\"],\n      lineSize: 2.5,\n      lineSmooth: true,\n      showMarker: true,\n      markerSize: 5,\n      chartArea: { fill: { color: C.midnight }, roundedCorners: true },\n      plotArea: { fill: { color: C.midnight } },\n      catAxisLabelColor: C.midGray,\n      valAxisLabelColor: C.midGray,\n      catAxisLabelFontSize: 9,\n      valAxisLabelFontSize: 9,\n      valGridLine: { color: \"2A3A6C\", size: 0.5 },\n      catGridLine: { style: \"none\" },\n      showLegend: true,\n      legendPos: \"b\",\n      legendFontSize: 9,\n      legendColor: C.midGray,\n    });\n\n    slide.addText(\"Plaintext HTTP is effectively extinct on the modern web.\", {\n      x: 5.0, y: 4.6, w: 4.5, h: 0.4,\n      fontFace: FONT_BODY, fontSize: 11, italic: true, color: C.midGray, margin: 0\n    });\n  }\n\n  // ════════════════════════════════════════════════\n  // SLIDE 6: HTTP/2 vs HTTP/3\n  // ════════════════════════════════════════════════\n  {\n    const slide = pres.addSlide();\n    slide.background = { color: C.offWhite };\n\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 0, y: 0, w: 10, h: 0.9, fill: { color: C.navy }\n    });\n    slide.addImage({ data: icons.rocket, x: 0.5, y: 0.18, w: 0.45, h: 0.45 });\n    slide.addText(\"HTTP/2 at ~58% While HTTP/3 Surges to 40%\", {\n      x: 1.1, y: 0.05, w: 8.5, h: 0.8,\n      fontFace: FONT_HEAD, fontSize: 24, color: C.white, bold: true, margin: 0\n    });\n\n    // Grouped bar chart: HTTP/2 vs HTTP/3 snapshot\n    slide.addChart(pres.charts.BAR, [\n      { name: \"HTTP/2\", labels: [\"Desktop\", \"Mobile\"], values: [58.6, 57.6] },\n      { name: \"HTTP/3\", labels: [\"Desktop\", \"Mobile\"], values: [38.7, 40.0] }\n    ], {\n      x: 0.5, y: 1.15, w: 4.5, h: 3.3,\n      barDir: \"col\",\n      barGrouping: \"clustered\",\n      showTitle: true,\n      title: \"Current Adoption (%)\",\n      titleColor: C.bodyText,\n      titleFontSize: 11,\n      chartColors: [C.deepBlue, C.accent],\n      chartArea: { fill: { color: C.white }, roundedCorners: true },\n      catAxisLabelColor: C.bodyText,\n      valAxisLabelColor: C.midGray,\n      catAxisLabelFontSize: 11,\n      valAxisLabelFontSize: 9,\n      valGridLine: { color: C.lightGray, size: 0.5 },\n      catGridLine: { style: \"none\" },\n      showValue: true,\n      dataLabelPosition: \"outEnd\",\n      dataLabelColor: C.darkText,\n      dataLabelFontSize: 10,\n      showLegend: true,\n      legendPos: \"b\",\n      legendFontSize: 10,\n      legendColor: C.bodyText,\n    });\n\n    // HTTP/3 rapid rise - inset time-series\n    const labels3 = [\"2020\", \"2021\", \"2022\", \"2023\", \"2024\", \"2025\"];\n    const h3Desktop = [0.1, 5, 12, 22, 32, 38.7];\n    const h3Mobile  = [0.7, 5, 13, 24, 34, 40.0];\n\n    slide.addChart(pres.charts.LINE, [\n      { name: \"Desktop H3\", labels: labels3, values: h3Desktop },\n      { name: \"Mobile H3\",  labels: labels3, values: h3Mobile }\n    ], {\n      x: 5.4, y: 1.15, w: 4.2, h: 2.4,\n      showTitle: true,\n      title: \"HTTP/3 Support Over Time (%)\",\n      titleColor: C.bodyText,\n      titleFontSize: 10,\n      chartColors: [C.deepBlue, C.accent],\n      lineSize: 2.5,\n      lineSmooth: true,\n      showMarker: true,\n      markerSize: 4,\n      chartArea: { fill: { color: C.white }, roundedCorners: true },\n      catAxisLabelColor: C.midGray,\n      valAxisLabelColor: C.midGray,\n      catAxisLabelFontSize: 8,\n      valAxisLabelFontSize: 9,\n      valGridLine: { color: C.lightGray, size: 0.5 },\n      catGridLine: { style: \"none\" },\n      showLegend: true,\n      legendPos: \"b\",\n      legendFontSize: 9,\n      legendColor: C.bodyText,\n    });\n\n    // Caveat\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 5.4, y: 3.75, w: 4.2, h: 1.0, fill: { color: C.white },\n      shadow: mkShadow()\n    });\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 5.4, y: 3.75, w: 0.08, h: 1.0, fill: { color: \"FFCC44\" }\n    });\n    slide.addText([\n      { text: \"Measurement Note: \", options: { bold: true, fontSize: 10, color: C.darkText, fontFace: FONT_BODY } },\n      { text: \"HTTP Archive measures HTTP/3 support, not actual usage. Fresh Chrome instances default to HTTP/2 before discovering HTTP/3 via Alt-Svc headers.\", options: { fontSize: 10, color: C.bodyText, fontFace: FONT_BODY } }\n    ], { x: 5.65, y: 3.8, w: 3.8, h: 0.9, margin: 0, lineSpacingMultiple: 1.15 });\n\n    slide.addText(\"Source: HTTP Archive State of the Web\", {\n      x: 0.5, y: 5.2, w: 5, h: 0.35,\n      fontFace: FONT_BODY, fontSize: 9, color: C.midGray, margin: 0\n    });\n  }\n\n  // ════════════════════════════════════════════════\n  // SLIDE 7: Font-Display Adoption\n  // ════════════════════════════════════════════════\n  {\n    const slide = pres.addSlide();\n    slide.background = { color: C.offWhite };\n\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 0, y: 0, w: 10, h: 0.9, fill: { color: C.navy }\n    });\n    slide.addImage({ data: icons.font, x: 0.5, y: 0.18, w: 0.45, h: 0.45 });\n    slide.addText(\"font-display Reaches 42% on Mobile\", {\n      x: 1.1, y: 0.05, w: 8.5, h: 0.8,\n      fontFace: FONT_HEAD, fontSize: 26, color: C.white, bold: true, margin: 0\n    });\n\n    slide.addText(\"Avoiding Flash of Invisible Text (FOIT) — but more than half of pages still at risk\", {\n      x: 0.6, y: 1.1, w: 9, h: 0.4,\n      fontFace: FONT_BODY, fontSize: 14, color: C.bodyText, margin: 0\n    });\n\n    // Bar comparison chart\n    slide.addChart(pres.charts.BAR, [\n      { name: \"Adoption %\", labels: [\"Desktop\", \"Mobile\"], values: [40.1, 42.5] }\n    ], {\n      x: 0.5, y: 1.7, w: 4.5, h: 2.8,\n      barDir: \"col\",\n      showTitle: true,\n      title: \"Current font-display Adoption\",\n      titleColor: C.bodyText,\n      titleFontSize: 11,\n      chartColors: [C.deepBlue],\n      chartArea: { fill: { color: C.white }, roundedCorners: true },\n      catAxisLabelColor: C.bodyText,\n      valAxisLabelColor: C.midGray,\n      catAxisLabelFontSize: 12,\n      valAxisLabelFontSize: 9,\n      valGridLine: { color: C.lightGray, size: 0.5 },\n      catGridLine: { style: \"none\" },\n      showValue: true,\n      dataLabelPosition: \"outEnd\",\n      dataLabelColor: C.darkText,\n      dataLabelFontSize: 12,\n      showLegend: false,\n    });\n\n    // Right side: Growth stat cards\n    const rx = 5.5, rw = 4.1;\n    // Desktop growth card\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: rx, y: 1.7, w: rw, h: 1.5, fill: { color: C.white },\n      shadow: mkShadow()\n    });\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: rx, y: 1.7, w: 0.08, h: 1.5, fill: { color: C.deepBlue }\n    });\n    slide.addText([\n      { text: \"40.1%\", options: { fontSize: 36, bold: true, color: C.deepBlue, fontFace: FONT_HEAD, breakLine: true } },\n      { text: \"Desktop · up 14.9% since 2020\", options: { fontSize: 12, color: C.midGray, fontFace: FONT_BODY } }\n    ], { x: rx + 0.3, y: 1.8, w: rw - 0.4, h: 1.3, margin: 0 });\n\n    // Mobile growth card\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: rx, y: 3.45, w: rw, h: 1.5, fill: { color: C.white },\n      shadow: mkShadow()\n    });\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: rx, y: 3.45, w: 0.08, h: 1.5, fill: { color: C.accent }\n    });\n    slide.addText([\n      { text: \"42.5%\", options: { fontSize: 36, bold: true, color: C.teal, fontFace: FONT_HEAD, breakLine: true } },\n      { text: \"Mobile · up 61.0% since 2020\", options: { fontSize: 12, color: C.midGray, fontFace: FONT_BODY } }\n    ], { x: rx + 0.3, y: 3.55, w: rw - 0.4, h: 1.3, margin: 0 });\n\n    slide.addText(\"Source: Lighthouse via HTTP Archive\", {\n      x: 0.5, y: 5.2, w: 5, h: 0.35,\n      fontFace: FONT_BODY, fontSize: 9, color: C.midGray, margin: 0\n    });\n  }\n\n  // ════════════════════════════════════════════════\n  // SLIDE 8: Key Takeaways\n  // ════════════════════════════════════════════════\n  {\n    const slide = pres.addSlide();\n    slide.background = { color: C.navy };\n\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 0, y: 0, w: 0.12, h: 5.625, fill: { color: C.accent }\n    });\n\n    slide.addImage({ data: icons.bullseye, x: 0.7, y: 0.35, w: 0.5, h: 0.5 });\n    slide.addText(\"Key Takeaways\", {\n      x: 1.35, y: 0.3, w: 7, h: 0.6,\n      fontFace: FONT_HEAD, fontSize: 32, color: C.white, bold: true, margin: 0\n    });\n    slide.addText(\"Bigger Pages, Smarter Protocols, Stronger Security\", {\n      x: 0.7, y: 0.95, w: 8.5, h: 0.4,\n      fontFace: FONT_BODY, fontSize: 16, color: C.midGray, margin: 0\n    });\n\n    // 5 takeaway cards\n    const takeaways = [\n      { num: \"1\", title: \"Page weight keeps climbing\", desc: \"Median desktop pages now transfer ~2,000 KB — roughly 25% heavier than 2020, driven by richer media and JavaScript.\" },\n      { num: \"2\", title: \"HTTPS is the new baseline\", desc: \"At 99%+ of requests, unencrypted HTTP is essentially extinct on the modern web.\" },\n      { num: \"3\", title: \"HTTP/3 is the fastest-growing metric\", desc: \"From near-zero to ~40% support in under four years, HTTP/3 is rapidly becoming mainstream.\" },\n      { num: \"4\", title: \"Fewer TCP connections despite more requests\", desc: \"Multiplexing in HTTP/2 and HTTP/3 cut median connections per page by 15–27%.\" },\n      { num: \"5\", title: \"font-display still underused\", desc: \"At ~40–42% adoption, significant room for improvement in avoiding invisible text during font loading.\" },\n    ];\n\n    const startY = 1.55;\n    const cardH = 0.68;\n    const gap = 0.1;\n\n    takeaways.forEach((t, i) => {\n      const cy = startY + i * (cardH + gap);\n      slide.addShape(pres.shapes.RECTANGLE, {\n        x: 0.7, y: cy, w: 8.6, h: cardH, fill: { color: C.midnight },\n        shadow: mkShadow()\n      });\n      // Number circle\n      slide.addShape(pres.shapes.OVAL, {\n        x: 0.9, y: cy + 0.12, w: 0.44, h: 0.44, fill: { color: C.accent }\n      });\n      slide.addText(t.num, {\n        x: 0.9, y: cy + 0.12, w: 0.44, h: 0.44,\n        fontFace: FONT_HEAD, fontSize: 16, bold: true, color: C.navy,\n        align: \"center\", valign: \"middle\", margin: 0\n      });\n      // Title + desc\n      slide.addText(t.title, {\n        x: 1.55, y: cy + 0.05, w: 7.5, h: 0.3,\n        fontFace: FONT_HEAD, fontSize: 14, bold: true, color: C.white, margin: 0\n      });\n      slide.addText(t.desc, {\n        x: 1.55, y: cy + 0.35, w: 7.5, h: 0.3,\n        fontFace: FONT_BODY, fontSize: 10.5, color: C.midGray, margin: 0\n      });\n    });\n\n    // CTA\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 0.7, y: 5.0, w: 8.6, h: 0.03, fill: { color: C.accent }\n    });\n    slide.addText(\"Benchmark your own site against these baselines at httparchive.org\", {\n      x: 0.7, y: 5.1, w: 8.6, h: 0.35,\n      fontFace: FONT_BODY, fontSize: 13, color: C.accent, bold: true, margin: 0\n    });\n  }\n\n  await pres.writeFile({ fileName: \"/app/output/final_deck.pptx\" });\n  console.log(\"Deck written to /app/output/final_deck.pptx\");\n}\n\nbuildDeck().catch(err => { console.error(err); process.exit(1); });\n", "numLines": 672, "startLine": 1, "totalLines": 672}}

