const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const { FaDatabase, FaWeightHanging, FaExchangeAlt, FaLock, FaRocket, FaFont, FaChartLine, FaBullseye } = require("react-icons/fa");

// ─── Palette: Ocean Gradient (deep blue / teal / midnight) ───
const C = {
  navy:      "0A1628",
  deepBlue:  "065A82",
  teal:      "1C7293",
  midnight:  "21295C",
  accent:    "00C9A7",  // mint accent for callouts
  accentAlt: "FF6B6B",  // coral for contrast
  white:     "FFFFFF",
  offWhite:  "F0F4F8",
  lightGray: "E2E8F0",
  midGray:   "94A3B8",
  darkText:  "1E293B",
  bodyText:  "334155",
};

const FONT_HEAD = "Georgia";
const FONT_BODY = "Calibri";

function renderIconSvg(IconComponent, color, size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

const mkShadow = () => ({ type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.12 });

async function buildDeck() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "HTTP Archive Analysis";
  pres.title = "State of the Web 2020–2025";

  // Pre-render icons
  const icons = {
    database: await iconToBase64Png(FaDatabase, "#" + C.accent, 256),
    weight:   await iconToBase64Png(FaWeightHanging, "#" + C.accent, 256),
    exchange: await iconToBase64Png(FaExchangeAlt, "#" + C.accent, 256),
    lock:     await iconToBase64Png(FaLock, "#" + C.accent, 256),
    rocket:   await iconToBase64Png(FaRocket, "#" + C.accent, 256),
    font:     await iconToBase64Png(FaFont, "#" + C.accent, 256),
    chart:    await iconToBase64Png(FaChartLine, "#" + C.white, 256),
    bullseye: await iconToBase64Png(FaBullseye, "#" + C.accent, 256),
  };

  // ════════════════════════════════════════════════
  // SLIDE 1: Title
  // ════════════════════════════════════════════════
  {
    const slide = pres.addSlide();
    slide.background = { color: C.navy };

    // Decorative top-left shape
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 0.12, h: 5.625, fill: { color: C.accent }
    });

    // Icon top area
    slide.addImage({ data: icons.chart, x: 0.7, y: 0.6, w: 0.7, h: 0.7 });

    slide.addText("State of the Web\n2020–2025", {
      x: 0.7, y: 1.5, w: 8.5, h: 1.8,
      fontFace: FONT_HEAD, fontSize: 42, color: C.white, bold: true,
      lineSpacingMultiple: 1.1, margin: 0
    });

    slide.addText("HTTP Archive Trends in Page Weight,\nProtocols, and Security", {
      x: 0.7, y: 3.3, w: 8.5, h: 0.8,
      fontFace: FONT_BODY, fontSize: 20, color: C.midGray, margin: 0,
      lineSpacingMultiple: 1.2
    });

    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: 4.35, w: 2.0, h: 0.03, fill: { color: C.accent }
    });

    slide.addText("Data Source: httparchive.org  |  Jan 2020 – Mar 2026", {
      x: 0.7, y: 4.6, w: 8.5, h: 0.4,
      fontFace: FONT_BODY, fontSize: 12, color: C.midGray, margin: 0
    });
  }

  // ════════════════════════════════════════════════
  // SLIDE 2: Crawl Sample Size Tripled
  // ════════════════════════════════════════════════
  {
    const slide = pres.addSlide();
    slide.background = { color: C.offWhite };

    // Title bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.9, fill: { color: C.navy }
    });
    slide.addImage({ data: icons.database, x: 0.5, y: 0.18, w: 0.45, h: 0.45 });
    slide.addText("Crawl Sample Size Tripled", {
      x: 1.1, y: 0.05, w: 8, h: 0.8,
      fontFace: FONT_HEAD, fontSize: 26, color: C.white, bold: true, margin: 0
    });

    // Subtitle
    slide.addText("From ~5M to 16M Desktop URLs Since 2020", {
      x: 0.6, y: 1.1, w: 9, h: 0.4,
      fontFace: FONT_BODY, fontSize: 15, color: C.bodyText, margin: 0
    });

    // Dual-line time-series chart
    const labels = ["Jan 2020", "Jul 2020", "Jan 2021", "Jul 2021", "Jan 2022", "Jul 2022", "Jan 2023", "Jul 2023", "Jan 2024", "Jul 2024", "Jan 2025"];
    const desktopURLs = [5, 5.2, 5.5, 5.8, 6.5, 14.5, 15.5, 16, 16, 16, 16];
    const mobileURLs  = [3.5, 3.7, 4, 4.3, 4.8, 10, 11.5, 12.5, 12.5, 12.5, 12.5];

    slide.addChart(pres.charts.LINE, [
      { name: "Desktop URLs (M)", labels: labels, values: desktopURLs },
      { name: "Mobile URLs (M)",  labels: labels, values: mobileURLs }
    ], {
      x: 0.5, y: 1.6, w: 9, h: 3.4,
      showTitle: false,
      chartColors: [C.deepBlue, C.accent],
      lineSize: 2.5,
      lineSmooth: false,
      showMarker: true,
      markerSize: 5,
      chartArea: { fill: { color: C.white }, roundedCorners: true },
      catAxisLabelColor: C.midGray,
      valAxisLabelColor: C.midGray,
      catAxisLabelFontSize: 8,
      valAxisLabelFontSize: 9,
      valGridLine: { color: C.lightGray, size: 0.5 },
      catGridLine: { style: "none" },
      showLegend: true,
      legendPos: "b",
      legendFontSize: 10,
      legendColor: C.bodyText,
    });

    // Annotation
    slide.addText("Sharp jump mid-2022: crawl expansion", {
      x: 5.2, y: 1.55, w: 3.5, h: 0.35,
      fontFace: FONT_BODY, fontSize: 10, italic: true, color: C.teal, margin: 0
    });

    // Source
    slide.addText("Source: HTTP Archive State of the Web", {
      x: 0.5, y: 5.2, w: 5, h: 0.35,
      fontFace: FONT_BODY, fontSize: 9, color: C.midGray, margin: 0
    });
  }

  // ════════════════════════════════════════════════
  // SLIDE 3: Page Weight Trends
  // ════════════════════════════════════════════════
  {
    const slide = pres.addSlide();
    slide.background = { color: C.offWhite };

    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.9, fill: { color: C.navy }
    });
    slide.addImage({ data: icons.weight, x: 0.5, y: 0.18, w: 0.45, h: 0.45 });
    slide.addText("Median Page Weight Climbs to ~2,000 KB", {
      x: 1.1, y: 0.05, w: 8.5, h: 0.8,
      fontFace: FONT_HEAD, fontSize: 26, color: C.white, bold: true, margin: 0
    });

    slide.addText("Desktop median up ~25% from ~1,600 KB (2020) · 75th percentile exceeds 4,000 KB", {
      x: 0.6, y: 1.1, w: 9, h: 0.4,
      fontFace: FONT_BODY, fontSize: 14, color: C.bodyText, margin: 0
    });

    // Line chart
    const labels = ["Jan 2020", "Jul 2020", "Jan 2021", "Jul 2021", "Jan 2022", "Jul 2022", "Jan 2023", "Jul 2023", "Jan 2024", "Jul 2024", "Jan 2025"];
    const desktopKB = [1600, 1650, 1700, 1750, 1800, 1850, 1880, 1920, 1950, 1975, 2000];
    const mobileKB  = [1450, 1500, 1550, 1600, 1650, 1700, 1740, 1780, 1830, 1870, 1900];

    slide.addChart(pres.charts.LINE, [
      { name: "Desktop (KB)", labels: labels, values: desktopKB },
